SELECT section, k1, k2, k3 FROM (SELECT 'schema' AS section, name AS k1, sql AS k2, NULL AS k3 FROM sqlite_schema WHERE name IN ('t1','t2','t3','sqlite_sequence') UNION ALL SELECT 't1', printf('%d',a), hex(b), quote(c) FROM t1 UNION ALL SELECT 't2', printf('%d',i), quote(b), quote(c) FROM t2 UNION ALL SELECT 't3', printf('%d',i), quote(b), quote(c) FROM t3 UNION ALL SELECT 'sequence', name, printf('%d',seq), NULL FROM sqlite_sequence) ORDER BY section, k1;